function personalLawShot(w){if(!inRoom()||inRoom().isHost||w.projectile)return false;camera.getWorldDirection(direction);ray.set(camera.position,direction);ray.far=w.range;const hit=ray.intersectObjects([...people.filter(p=>p.hp>0&&!p.vehicle).map(p=>p.root),...vehicles.filter(v=>!v.destroyed&&(!v.hostile||v.deployed)).map(v=>v.root)],true)[0];if(!hit)return false;let node=hit.object;while(node&&!node.userData.actor)node=node.parent;if(!node||!personalLaw(node.userData.actor)||lineBlocked(camera.position,hit.point,blocks))return false;applyImpact(hit,w.damage);tracer(camera.position,hit.point);updateHud();return true}
