function friendlyTarget(from,range){let best=null,bestD=range;for(const {rig,pose} of networkPeers.values()){if(pose.hp<=0||!pose.active)continue;const point=actorPoint(rig),d=Math.hypot(from.x-point.x,from.y-point.y,from.z-point.z);if(d<bestD&&!lineBlocked(from,point,blocks)){best={actor:rig,point};bestD=d}}if(!trip&&!busRide&&canReceiveAttack(civic.state.justice,from)){const point={x:player.x,y:player.y+1.3,z:player.z},d=Math.hypot(from.x-point.x,from.y-point.y,from.z-point.z);if(d<bestD&&!lineBlocked(from,point,blocks)){best={actor:null,point};bestD=d}}for(const a of allyIndex.query(from.x,from.z,range)){if(a.hp<=0)continue;const point=actorPoint(a),d=Math.hypot(from.x-point.x,from.y-point.y,from.z-point.z);if(d<bestD&&!lineBlocked(from,point,blocks)){best={actor:a,point};bestD=d}}return best}
