function enemyEngageAlly(p,victim,dt){const pos=p.root.position,end=victim.point,dx=end.x-pos.x,dz=end.z-pos.z,d=Math.hypot(dx,dz);p.root.rotation.y=Math.atan2(-dx,-dz);let moving=false;if(d>18){moveBody(pos,dx/d*dt*2,dz/d*dt*2,blocks,.42);moving=true}if(p.reloading>0){p.reloading=Math.max(0,p.reloading-dt);if(!p.reloading)p.ammo=8}else{p.cool-=dt;if(p.cool<=0){p.cool=.55;p.ammo--;p.recoil=1;tracer({x:pos.x,y:1.4,z:pos.z},end,0xff946e);if(world.rand()<.65)hurtFriendly(victim,8);if(p.ammo<=0)p.reloading=2.4}}animatePerson(p,dt,moving)}
