let wallet=50000,supplies={medkit:2,armor:1},bankCooldowns={},robbery=null;

function bagCanUse(){return active&&!ended&&!['station','court','prison'].includes(civic.state.justice)}
function consumeSupply(kind){if(!bagCanUse())return false;const ok=useSupply(supplies,player,kind);if(ok){message(SUPPLIES[kind].name+' 사용 완료');updateHud()}return ok}
function buySupply(kind){if(!Object.hasOwn(SUPPLIES,kind))return false;if(wallet<SUPPLIES[kind].cost||supplies[kind]>=10)return false;collectSupply(supplies,kind);wallet-=SUPPLIES[kind].cost;updateHud();return true}
function startRobbery(bank){if(robbery||!active||ended||currentVehicle||trip||busRide||drones.piloting||!robberyAllowed(bank,player,elapsed,bankCooldowns,civic.state.justice))return false;robbery={bank,x:player.x,z:player.z,health:player.health,armor:player.armor,progress:0};civic.state.justice='wanted';civic.state.justiceTime=0;civic.officers.forEach(o=>o.deployed=false);message('은행 경보 · 금고 옆에서 8초 대기 · 이동하거나 피해를 받으면 중단',6);return true}
function updateRobbery(dt){if(!robbery)return;const status=advanceRobbery(robbery,dt,player,active&&!ended&&!currentVehicle&&!trip&&!busRide&&!drones.piloting&&!bagUI.opened&&!phone.opened&&!['station','court','prison'].includes(civic.state.justice));if(status==='cancel'){robbery=null;message('은행 강도 중단 · 돈을 가져오지 못했습니다.',4)}else if(status==='complete'){wallet=Math.min(1e9,wallet+robbery.bank.reward);bankCooldowns[robbery.bank.id]=Math.ceil(elapsed+BANK_COOLDOWN);message(robbery.bank.name+' 강도 성공 · +'+robbery.bank.reward.toLocaleString()+'원 · 경찰 추격',6);robbery=null;updateHud()}}
function bankPrompt(){if(robbery)return '금고에서 돈을 챙기는 중 · '+Math.max(0,BANK_DURATION-robbery.progress).toFixed(1)+'초';const bank=bankWorld.near(player);if(!bank)return '';const remaining=Math.ceil((bankCooldowns[bank.id]||0)-elapsed);return remaining>0?bank.name+' · 금고 비어 있음 · '+remaining+'초 후 보충':'E · '+bank.name+' 금고 털기 · '+bank.reward.toLocaleString()+'원'}

function closeCityMenu(){$('citypanel').hidden=true;requestPlay()}
function openCityMenu(title){active=false;shooting=false;aim=false;keys.clear();$('citytitle').textContent=title;$('citychoices').replaceChildren();$('citypanel').hidden=false;document.exitPointerLock?.()}
function showAtlas(){drones.recall();if(peninsula.active){peninsula.menu();return}if(['station','court','prison'].includes(civic.state.justice)){message('구금 중에는 지역 이동을 사용할 수 없습니다.');return}openCityMenu('서울 상세맵 확장 · 전국 도시');$('citydescription').textContent='기존 서울 상세맵과 같은 세계에서 도로·기차·비행기로 이어지는 확장 지역입니다. 도시 중심 빠른 이동 또는 실제 역·공항에서 탑승하세요.';for(const region of EXPANDED_CITIES){const button=document.createElement('button');button.textContent=region.name+' · 상세맵 확장 구역';button.onclick=()=>warpExpanded(region);$('citychoices').append(button)};for(const a of [...metropolis.anchors,{name:'국회의사당 · 로비 / 본회의장',x:-285,z:191},...civic.destinations,...bankWorld.banks]){const b=document.createElement('button');b.textContent=a.name;b.onclick=()=>{if(currentVehicle){if(inRoom())multiplayer.release(vehicles.indexOf(currentVehicle)).catch(()=>{});currentVehicle.occupied=false;currentVehicle.speed=0;currentVehicle=null}if(busRide){busRide.service.passenger=false;busRide=null}trip=null;for(const p of transport.platforms.values()){slideDoors(p,0);p.root.visible=false}const p=metropolis.safeSpawn(a);Object.assign(player,p,{y:0,vy:0,grounded:true});yaw=Math.PI;pitch=0;closeCityMenu();message(a.name+' 이동 · 지도 M / 지역 이동 G',5)};$('citychoices').append(b)}}
function showShop(f){openCityMenu(f.name);for(const kind of Object.keys(SUPPLIES)){const button=document.createElement('button');button.textContent=SUPPLIES[kind].name+' 보관 · '+SUPPLIES[kind].cost.toLocaleString()+'원';button.onclick=()=>{$('citydescription').textContent=buySupply(kind)?'구매 완료 · I 인벤토리에 보관 · 잔액 '+wallet.toLocaleString()+'원':'잔액이 부족하거나 보관함이 가득 찼습니다.'};$('citychoices').append(button)}$('citydescription').textContent='잔액 '+wallet.toLocaleString()+'원 · 물품을 구매하면 체력이 회복됩니다.';for(const item of SHOP_ITEMS){const b=document.createElement('button');b.textContent=item.name+' · '+item.cost.toLocaleString()+'원';b.onclick=()=>{const result=purchaseItem(wallet,player.health,item.id);if(!result.ok){$('citydescription').textContent='잔액이 부족합니다.';return}wallet=result.wallet;player.health=result.health;$('citydescription').textContent='구매 완료 · 잔액 '+wallet.toLocaleString()+'원 · 체력 '+Math.ceil(player.health);updateHud()};$('citychoices').append(b)}}

function requestPlay(){if(ended)return;try{if(!mobileMode){const p=$('game').requestPointerLock();p?.catch(()=>message('마우스 잠금 제한 · 방향키로 시점 조작 가능'))}}catch{}active=true;started=true;$('menu').hidden=true;$('pause').hidden=true;$('hud').hidden=false;$('foot').hidden=true;sound('start');updateHud()}
function pause(){bagUI.close(false);robbery=null;phone.close(false);if(!active)return;drones.recall();peninsula.stopCombat();active=false;touchControls?.reset();shooting=false;aim=false;keys.clear();$('pause').hidden=false;document.exitPointerLock?.()}
function finish(){phone.close(false);drones.recall();active=false;ended=true;shooting=false;aim=false;keys.clear();document.exitPointerLock?.();$('hud').hidden=true;$('pause').hidden=true;$('result').hidden=false;$('resulttag').textContent='SIGNAL LOST';$('resulttitle').textContent='작전 실패';$('resultbody').textContent=`적 ${kills} / ${enemies.length} 제압 · 방탄복과 구급상자를 확보해 재도전하세요.`}
function reset(resume=true){bagUI.close(false);robbery=null;supplies={medkit:2,armor:1};bankCooldowns={};phone.close(false);drones.reset();droneProjectileSequence=0;regionalFlight=null;journeyAircraft.visible=false;mapExpanded=false;$('mapbox').classList.toggle('expanded',false);peninsula.resetBattle();if(peninsula.active)peninsula.exit();airWeapons.reset();civic.reset();Object.assign(player,{x:220,z:-115,y:0,vy:0,health:PLAYER_MAX_HEALTH,armor:0,grounded:true});wallet=50000;$('citypanel').hidden=true;active=false;ended=false;kills=0;elapsed=0;lastDamage=-99;currentVehicle=null;trip=null;stationMenu=null;busRide=null;waitingStop=null;waitClock=0;servedStop=null;for(const bus of transport.buses){bus.service=createBusService(bus.service.home);bus.root.visible=false;slideDoors(bus,0)}for(const p of transport.platforms.values())slideDoors(p,0);for(const train of trains){train.distance=0;slideDoors(train,0)}reload=0;fireCooldown=0;recoil=0;hit=0;hurt=0;aim=false;shooting=false;yaw=0;pitch=0;keys.clear();inventory.forEach((it,i)=>Object.assign(it,{owned:i===0||i===4,ammo:WEAPONS[i].mag,reserve:WEAPONS[i].reserve}));people.forEach(p=>{p.root.position.set(p.origin.x,0,p.origin.z);p.body.rotation.set(0,0,0);p.body.position.y=0;p.hp=p.role==='security'?180:100;p.aiElapsed=-(p.phase%1)*.35;p.death=0;p.reloading=0;p.ammo=p.role==='security'?24:8;p.cool=1+world.rand();p.flee=0;if(p.muzzle)p.muzzle.visible=false});vehicles.forEach(v=>{Object.assign(v,v.origin,{speed:0,y:0,occupied:false,destroyed:false,trafficOffset:v.origin.trafficOffset??vehicles.indexOf(v)*71});v.root.position.set(v.x,0,v.z);v.root.rotation.y=v.yaw});resetHostileVehicles();for(const a of allies){a.vehicle=null;a.cool=1;a.aiElapsed=-(a.patrolId%8)*.05;a.patrolLeg=0;a.patrolAt=0;a.patrolPoint=null;a.assignedVehicle=a.driver?alliedVehicles[allies.indexOf(a)]:null}for(const v of vehicles)v.allyPilot=null;refreshCombatIndices(0,true);for(const r of rockets){scene.remove(r.mesh);r.mesh.geometry.dispose();r.mesh.material.dispose()}rockets.length=0;vehicles.forEach(v=>v.hp=650);pickups.forEach(p=>{p.respawn=0;p.root.visible=true});for(const e of effects){scene.remove(e.line);e.line.geometry.dispose();e.line.material.dispose()}effects.length=0;$('result').hidden=true;$('transit').hidden=true;$('radio').textContent='아군 50명 자율 작전 · G 지역 이동 → 국회의사당 내부 · M 지도';operation.reset();offensive.reset();equip(0);phone.render();message('강북 성수 방면에서 시작합니다 · 근처 보급품을 확보하세요.',6);if(resume)requestPlay()}
$('cityclose').onclick=closeCityMenu;
