function mobileAction(action,down){if(action==='bag'&&down){bagUI.toggle();return}if(bagUI.opened)return;if(action==='phone'&&down){phone.toggle();return}if(down&&!active)return;if(action==='drone'&&down){drones.toggle();return}if(peninsula.active){if(action==='fire'){peninsula.setTrigger(down);return}const hold={jump:'Space',descend:'KeyC',brake:'ShiftLeft'}[action];if(hold){if(down)keys.add(hold);else keys.delete(hold);return}if(!down)return;if(action==='aim')aim=!aim;if(action==='heat')peninsula.airAction('heat');if(action==='flare')peninsula.airAction('flare');if(action==='reload')peninsula.reload();if(action==='weapon'){for(let n=1;n<=5;n++){const index=(selected+n)%5;if(inventory[index].owned){equip(index);break}}}if(action==='interact')peninsula.interact();if(action==='atlas')peninsula.menu();if(action==='map')peninsula.toggleMap();if(action==='pause')pause();if(action==='account')$('profilebutton').click();return}if(action==='fire'){shooting=down;if(down)shoot();return}const holds={jump:'Space',descend:'KeyC',brake:'ShiftLeft'};if(holds[action]){if(down)keys.add(holds[action]);else keys.delete(holds[action]);if(action==='jump'&&down&&!drones.piloting&&!currentVehicle&&!trip&&!busRide&&player.grounded){player.vy=7.8;player.grounded=false}return}if(!down)return;if(action==='heat'||action==='flare')airAction(action);if(action==='aim')aim=!aim;if(action==='interact')interact();if(action==='reload')doReload();if(action==='weapon'&&!currentVehicle&&!trip&&!busRide){for(let n=1;n<WEAPONS.length+1;n++){const i=(selected+n)%WEAPONS.length;if(inventory[i].owned){equip(i);break}}}if(action==='pause')pause();if(action==='atlas')showAtlas();if(action==='map'){mapExpanded=!mapExpanded;$('mapbox').classList.toggle('expanded',mapExpanded);drawMap()}if(action==='account')$('profilebutton').click()}
