const peninsula=buildPeninsula(T,{message,sound,online:()=>!!inRoom(),authority:()=>!inRoom()||inRoom().isHost,uid:()=>inRoom()?.uid||'solo',peers:()=>Array.from(networkPeers,([uid,e])=>({...e.pose,uid})),claim:id=>inRoom()?multiplayer.claim(id):Promise.resolve(true),release:id=>multiplayer?.release?.(id),damagePeer:(uid,n)=>multiplayer?.damagePeer(uid,n),sendShot:shot=>{if(inRoom()&&!inRoom().isHost){multiplayer.shoot(shot);return true}return false},sendUse:action=>{const p=peninsula.position;multiplayer?.shoot({kind:'use',action,weapon:selected,origin:{x:p.x,y:p.y+1.7,z:p.z},direction:{x:0,y:0,z:-1}})},sendAir:kind=>{const p=peninsula.position;multiplayer?.shoot({kind,weapon:selected,origin:{x:p.x,y:p.y+1.7,z:p.z},direction:{x:0,y:0,z:-1}})},setView(angle){yaw=angle;pitch=0},animate:animatePerson,wallet:()=>wallet,treat(){player.health=500},shop(){showShop({name:'지역 편의점'})},disarm(){inventory.forEach(it=>Object.assign(it,{owned:false,ammo:0,reserve:0}));selected=0;aim=false},arm(){Object.assign(inventory[0],{owned:true,ammo:30,reserve:90});selected=0},state:()=>({health:player.health,armor:player.armor,inventory,selected,aim,mobile:mobileMode,active}),canAct:()=>active&&!ended,hurt:(amount,origin)=>{peninsula.battle?.noteDamage();damage(amount,origin)},heal:amount=>player.health=Math.min(500,player.health+amount),hit(){hit=.16},hitVisible:()=>hit>0,supply(){player.health=500;player.armor=100;inventory.forEach((it,i)=>Object.assign(it,{owned:true,ammo:WEAPONS[i].mag,reserve:WEAPONS[i].reserve}))},resetLook(){yaw=0;pitch=0},resume:requestPlay,closeMenu:closeCityMenu,exit(){yaw=0;pitch=0;updateHud();drawMap()},menu(title,description,items){openCityMenu(title);$('citydescription').textContent=description;for(const item of items){const button=document.createElement('button');button.textContent=item.label;button.onclick=item.action;$('citychoices').append(button)}}});
function enterPeninsula(){if(inRoom()&&!inRoom().isHost){message('방장이 한반도 맵으로 전환하면 함께 이동합니다.',5);return}if(['station','court','prison'].includes(civic.state.justice)){message('구금 중에는 지역 이동을 사용할 수 없습니다.',4);return}if(currentVehicle||trip||busRide){message('하차 후 한반도 이동 모드로 진입하세요.',4);return}$('citypanel').hidden=true;shooting=false;aim=false;keys.clear();yaw=0;pitch=0;peninsula.enter()}
